const input = $input.first().json || {};

const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || {};

function clean(value, max = 3500) {
  if (value === undefined || value === null) return "";
  return String(value).slice(0, max);
}

const workflowName = workflow.name || "Unknown workflow";
const nodeName = execution.lastNodeExecuted || "Unknown node";
const message = clean(error.message || "Unknown error");

const telegramBaseMessage = [
  "🚨 Lead workflow failed",
  "",
  `Workflow: ${workflowName}`,
  `Node: ${nodeName}`,
  `Execution: ${execution.id || "unknown"}`,
  execution.url ? `URL: ${execution.url}` : "",
  execution.retryOf ? `Retry of: ${execution.retryOf}` : "",
  execution.mode ? `Mode: ${execution.mode}` : "",
  "",
  `Error: ${message}`
].filter(Boolean).join("\n");

return [
  {
    json: {
      workflow_id: workflow.id || null,
      workflow_name: workflowName,
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      retry_of: execution.retryOf || null,
      execution_mode: execution.mode || null,

      node_name: nodeName,
      severity: "critical",
      event_type: "ERROR",
      error_message: message,
      error_stack: clean(error.stack, 7000),

      telegram_base_message: telegramBaseMessage,
      raw_payload: input
    }
  }
];

const error = $('Normalize Error Payload').first().json;
const resolved = $input.first().json || {};

const eventId = resolved.event_id || null;
const leadId = resolved.lead_id || null;

const telegramMessage = [
  error.telegram_base_message,
  "",
  eventId ? `Event ID: ${eventId}` : "Event ID: not found",
  leadId ? `Lead ID: ${leadId}` : "Lead ID: not found",
  resolved.external_id ? `External ID: ${resolved.external_id}` : "",
  resolved.processing_status ? `Current status: ${resolved.processing_status}` : ""
].filter(Boolean).join("\n");

return [
  {
    json: {
      ...error,

      event_id: eventId,
      lead_id: leadId,
      external_id: resolved.external_id || null,
      processing_status: resolved.processing_status || null,
      event_payload: resolved.event_payload || null,

      telegram_message: telegramMessage
    }
  }
];
